"""Checkpoint toolkit completion and the first Rootstock source pass."""
from pathlib import Path
from datetime import datetime, timezone
import hashlib, json, subprocess
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[2]
NAME='workspace_rootstock_review_receipt.json'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
load=lambda n:json.loads((HERE/n).read_text(encoding='utf-8-sig'))
def git(*a):return subprocess.check_output(['git',*a],cwd=ROOT,text=True).strip()
def save(n,v):(HERE/n).write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8')
assert not (HERE/NAME).exists()
old=load('list_session_review_receipt.json')
head=git('rev-parse','HEAD');assert head==old['basis_commit']
guards={**old['preserved_production_and_test_hashes'],**old['source_sha256']};assert len(guards)==1562
assert all(sha(ROOT/n)==h for n,h in guards.items())
assert all(sha(HERE/n)==h for n,h in old['evidence_sha256'].items())
assert sha(ROOT/old['partial_source']['path'])==old['partial_source']['sha256']
doc=ROOT/old['document']['path'];prefix=doc.read_bytes();assert sha(doc)==old['document']['sha256']
assert all(sha(ROOT/n)==h for n,h in old['shared_working_file_sha256'].items() if n!=old['document']['path'])
index=Path(git('rev-parse','--git-path','index'));index=index if index.is_absolute() else ROOT/index;index_hash=sha(index)
inv,cov=load('source_inventory.json'),load('read_coverage.json')
