whole=sorted(n for n,v in inv['files'].items() if n.startswith(('crates/cambium/cambium/','crates/cambium/cambium-rootstock/')) and n not in guards and cov.get(n,{}).get('sha256')==v['sha256'] and cov[n]['through']==v['chars'])
assert len(whole)==17 and sum(inv['files'][n]['chars'] for n in whole)==258511
assert all(sha(ROOT/n)==inv['files'][n]['sha256'] for n in whole)
toolkit={n:v for n,v in inv['files'].items() if n.startswith('crates/cambium/cambium/')}
assert len(toolkit)==80 and sum(v['chars'] for v in toolkit.values())==1456738
assert all(cov.get(n,{}).get('sha256')==v['sha256'] and cov[n]['through']==v['chars'] and sha(ROOT/n)==v['sha256'] for n,v in toolkit.items())
stats=json.loads(subprocess.check_output(['python',str(HERE/'read_coverage.py'),'status'],cwd=ROOT))
assert stats['complete_files']==2049 and stats['read_chars']==24574199 and not stats['changed_since_inventory'] and not stats['pending_chunks']
probe=load('workspace_float_probe_receipt.json')
assert probe['build_exits']==[0,0] and probe['run_exit']==0 and probe['checks']==3 and probe['generated_output_removed']
assert all(not Path(o['path']).exists() for o in probe['removed_outputs'])
assert all(sha(ROOT/n)==h for n,h in probe['source_sha256'].items())
assert all(sha(Path(v['path']))==v['sha256'] for v in probe['libraries'].values())
notes,authority=load('review_notes.json'),load('authority_map.json')
assert notes['findings'][-1]['id']=='Q304' and authority['entries'][-1]['id']=='A766'
finding={'id':'Q305','title':'Raising a floating pane transfers component-local state to another tile',
 'source':'crates/cambium/cambium/src/workspace.rs:146,181',
 'status':'verified original current default-feature toolkit over retained exact dependency artifacts',
 'evidence':'workspace_view_with_marks and the presented variant build the visible floating tiles as an unkeyed Vec<PaneView>. Workspace activation raises a float by changing its z order, so the positional child view state is rebuilt with a different tile prop. In the executed current workspace_view path, float 1 owns count 1 and float 2 owns count 0; an unchanged-order refresh preserves both. Raising float 1 reuses its node/count for float 2 and the original float-2 node/count for float 1. Another real button click increments the wrong-owner inherited count to 2. The host workspace and model identity change correctly; the view custody is positional. This is distinct from the documented tree/float or cross-projection rebuild boundary because neither tile changes station. The presented path shares the same unkeyed construction and renderer by source trace, but was not separately executed. No native floating windows, layout, persistence or product-local owner data were exercised.',
 'verification':NAME,'diagnostics':['workspace_float_probe_receipt.json'],
 'repair_triage':{'disposition':'documented; production unchanged under active read-only audit goal','reason':'Key the floating view sequence by TileId in both rendering entry points and preserve the existing shared float renderer. Verify raise, close, hidden unpinned floats and presented variants with distinct component state and focus. Do not add a second persisted pane store.'}}
notes['findings'].append(finding)
rows=[
 ('Integration-test evidence has explicit limits','Toolkit tests establish headless DOM/state contracts, not native layout or complete event convergence.', ['crates/cambium/cambium/src/tests.rs'], 'All 131,598 characters are now read. The portable target-before-source test explicitly expects fresh build/drain, reinforcing Q294. Multi-runner tests cover separate documents/shared application state, not forest custody Q301. Stacked listeners and stop-propagation are tested independently, leaving Q296 interaction uncovered. Normal focus, key, pointer capture, stale-node/default and control tests are real source evidence; they were not broadly executed this pass.'),
 ('Workspace station and float identity authority','The host owns Workspace and keyed durable pane state; the float view sequence does not retain TileId identity.', ['crates/cambium/cambium/src/workspace.rs'], 'Workspace delegates tree presentation to Frisket and float tabs to tab_bar_view. Cross-projection and tree/float rebuilding are honestly documented. Q305 exposes an additional same-station state transposition on float raising. Both ordinary/presented functions separately construct unkeyed float Vecs, while render_float is shared. Local preservation prose must include both the Q294 ordering limit and the float-identity failure.'),
 ('Primitive views and single-path input wrappers','Text constructors delegate one OrphanView backend; numeric-value and wheel wrappers each maintain one per-node path.', ['crates/cambium/cambium/src/text.rs','crates/cambium/cambium/src/value.rs','crates/cambium/cambium/src/wheel.rs'], 'String/number views update character data and reject routed messages as Stale. Value/Wheel independently repeat the build/rebuild/teardown/message registration skeleton; Wheel explicitly documents a single handler without capture/bubble. ValueEvent documents host finite-value preconditions rather than validating in the wrapper. These differ from click/key vector registries, so broad uniform-native-event claims need scope qualification.'),
 ('Title and pane status are presentation inputs','TitleBar and Instrument pane headers carry caller identity, states and actions without authoring window commands or document state.', ['crates/cambium/cambium/src/title_bar.rs','crates/cambium/cambium/src/title_bar.css','crates/cambium/cambium/src/workspace_chrome.rs','crates/cambium/cambium/tests/instrument.rs'], 'Caption spacing/drag regions are stylesheet-host contracts. Active/selected/dirty/loading remain independent host facts. Instrument source tests prove attention does not open material and status updates preserve the action node/focus; these tests were read, not executed this pass. All eighty inventoried toolkit files are completely read at current hashes.'),
 ('Capture delegates rendering and binds appearance lifetime','Rootstock capture wraps render-host readbacks and checks stamp, pixel extent and cancellation independently of a borrowed host.', ['crates/cambium/cambium-rootstock/src/capture.rs','crates/cambium/cambium-rootstock/src/capture/scope.rs'], 'Pending readback uses the supplied Surface render core and original PresentedFrame; CaptureOwner/Scope independently invalidate jobs on generation change/disposal and recheck cancellation after poll. ScopedCapture rejects foreign stamp/extent before returning pixels. Synchronous compatibility read_frame maps errors to None and logs them. Current GPU pixels/reentrant host scenarios were not executed in this pass.'),
 ('Embedding separates owner facts from appearance/GPU state','Rootstock embedding View owns appearance visibility/focus/capture; callbacks own device-bound scene resources only.', ['crates/cambium/cambium-rootstock/Cargo.toml','crates/cambium/cambium-rootstock/src/embedding.rs','crates/cambium/cambium-rootstock/src/embedding/gpu.rs'], 'View routes admitted owner input through caller callbacks, offsets coordinates, asks the supplied producer for scenes/semantics and retires it on disposal. Gpu uses supplied device/queue/encoder and delegates sparse scene rendering to HybridSession; configuration/device/encoding/size failures are typed errors. Generation recovery preserves owner state outside the adapter. Placement bounds and scale validation do not prove nonoverflowing physical size; no optional-feature compile/GPU receipt was run.'),
 ('Egui input and callback authority remain explicit','Egui adapter maps toolkit events and uses per-appearance GPU state; caller grants focus and handles copy/cut.', ['crates/cambium/cambium-rootstock/src/embedding/egui.rs','crates/cambium/cambium-rootstock/src/embedding/egui_input.rs','crates/cambium/cambium-rootstock/src/accessibility_tests.rs'], 'Egui input converts IME character selections to bytes and refuses unexpressible delete-surrounding/extra buttons. Window deactivation revokes focus but activation does not grant every appearance keyboard authority. Callback epoch/generation/appearance checks guard lazy GPU setup and clip at painting. Accessibility test source checks live runner focus independently of restyle cache and bounds after scrolling. Callback prepare/paint scheduling, optional features and native accessibility remain unexecuted here.')
]
entries=[{'id':f'A{767+i}','domain':d,'claim':c,'implementations':paths,'assessment':a,'state':'current source read; focused float identity check only','verification':NAME} for i,(d,c,paths,a) in enumerate(rows)]
authority['entries'].extend(entries)
notes.setdefault('review_followups',[]).extend([
 {'verification':NAME,'area':'Optional embedding callback scheduling','detail':'Finish Iced/input/tests and trace toolkit prepare/paint ordering, shared per-appearance GPU state, error/epoch paths and multiple callbacks before making scheduling or frame-identity findings. No optional-feature build or GPU execution this pass.'},
 {'verification':NAME,'area':'Embedding visibility and owner input lifetime','detail':'Inspect hosts for focus/capture/IME cancellation on set_visible(false), producer suspend/retire semantics and finite physical-size conversion. Local appearance flags alone do not demonstrate owner cancellation or resource recovery.'}
])
notes.setdefault('completed_source_areas',[]).append({'prefix':'crates/cambium/cambium/','files':80,'chars':1456738,'verification':NAME,'basis_commit':head,'qualification':'All inventoried source/manifests/styles/tests read at current hashes; not full supplier/optional-feature/native acceptance.'})
next_read={'path':'crates/cambium/cambium-rootstock/src/embedding/iced.rs','start':0,'reason':'Continue Rootstock embedding adapters/tests, then host routing/layout/paint/lifetime code, native/web adapters and all remaining Mere source.'}
notes['current_area']='Toolkit complete; Rootstock capture, initial embedding/GPU/egui and accessibility tests read'
notes['next_area']=next_read['reason']
notes['checkpoint']={'classification':'progress','classification_of_previous_turn':'progress','goal_status':'active; full source incomplete','coverage':stats,'finding_count':len(notes['findings']),'authority_entries':len(authority['entries']),'new_receipts':[NAME,'workspace_float_probe_receipt.json'],'audit_authored_production_edits_this_turn':False,'next_read':next_read,'pending_verification':None,'diagnostic_outcomes':'Three current-toolkit floating-identity checks pass over retained hash-bound dependencies; Rootstock optional modules were read but not compiled or run.'}
diff=subprocess.run(['git','diff','--check'],cwd=ROOT,capture_output=True,text=True);assert diff.returncode==0
with (HERE/'workspace_rootstock_diff_check.txt').open('x',encoding='utf-8') as f:f.write(diff.stdout+diff.stderr)
evidence=['record_workspace_rootstock_review.py','workspace_rootstock_diff_check.txt','workspace_float_probe.rs','run_workspace_float_probe.py','workspace_float_probe_receipt.json','workspace_float_probe_compile_0.log','workspace_float_probe_compile_1.log','workspace_float_probe_output.log']
addition=f'''

### Toolkit complete; floating identity and Rootstock boundaries, 2026-10-17

All 80 inventoried Cambium toolkit files / 1,456,738 characters are now fully read at current hashes. This pass finishes the 131,598-character integration-test module and the remaining text, wheel/value, title/pane chrome and workspace sources, then reads Rootstock capture/lifetime, initial embedding/GPU/egui and accessibility-test source. Seventeen files are newly complete; 248,048 additional characters were read because the integration-test prefix was already credited. Overall coverage is {stats['complete_files']:,}/{stats['total_files']:,} files and {stats['read_chars']:,}/{stats['total_chars']:,} characters, with no stale hashes or pending chunks. Full-source review remains incomplete.

Q305 verifies floating pane state transposition. Ordinary and presented workspace entry points construct visible float views as unkeyed Vecs. Raising float 1 changes model z order; positional reconciliation then gives float 2 the original float-1 node and local count 1, while float 1 takes float 2's node/count 0. An unchanged-order control preserves identity, and another actual callback increments the inherited wrong-owner count to 2. This happens within the float station, independently of the documented tree/float or cross-projection rebuild boundary. The ordinary path was executed; the presented variant shares the construction/renderer by source trace only. The [checkpoint](../../../support/receipts/authority-success-audit/{NAME}) binds three current original-toolkit checks over exact retained dependency artifacts; generated build outputs were recorded and removed. No native float windows, layout, durable pane state or whole-current supplier graph was tested.

A767-A773 record the integration tests' actual limits, workspace station identity, primitive/single-path event wrappers, presentation-only title/pane status, appearance-bound capture delegation, owner/appearance/GPU separation and egui input/callback authority. Existing source tests explicitly expect target-before-source child replacement, qualifying Q294; multi-runner tests do not establish Q301 forest preservation, and separate stacked/stop-propagation tests omit Q296's interaction. Workspace prose is honest about cross-projection loss but overstates general local preservation. Per-node wheel/value wrappers repeat registration machinery and have narrower semantics than click/key's vector registry.

CaptureScope checks disposal/generation, post-poll cancellation and stamp/pixel extent; GPU readback is delegated to render-host. Embedding uses supplied owner callbacks and GPU handles, with typed refusal paths and no storage authority in rendering callbacks. Rootstock optional egui/GPU modules and accessibility tests were read, not compiled or executed in this pass. Remaining adapter scheduling, visibility/input cancellation and finite physical-size boundaries are documented follow-ups, not product failures. Production/shared WIP remain byte-preserved, prior audit text is an exact prefix, and the index is unchanged. No isolated target, Cargo home or worktree was created. Continue with Rootstock embedding/iced.rs.
'''
doc.write_bytes(prefix+addition.encode('utf-8'));save('review_notes.json',notes);save('authority_map.json',authority)
